  "(knowledge base v{s}), {s} ·": { "es": "(base de conocimiento v{s}), {s} ·", "pt": "(base de conhecimento v{s}), {s} ·", "fr": "(base de connaissances v{s}), {s} ·" },
  "(knowledge base v{s}), {s}": { "es": "(base de conocimiento v{s}), {s}", "pt": "(base de conhecimento v{s}), {s}", "fr": "(base de connaissances v{s}), {s}" },
  "Open emergency help": { "es": "Abrir ayuda de emergencia", "pt": "Abrir ajuda de emergência", "fr": "Ouvrir l’aide d’urgence" },
  "Record this symptom": { "es": "Registrar este síntoma", "pt": "Registrar este sintoma", "fr": "Noter ce symptôme" },
  "No risks ahead at the current trends. Keep logging so the predictions stay accurate.": { "es": "No hay riesgos por delante con las tendencias actuales. Sigue registrando para que las predicciones sean precisas.", "pt": "Sem riscos à frente com as tendências atuais. Continue registrando para manter as previsões precisas.", "fr": "Aucun risque à venir avec les tendances actuelles. Continuez à noter pour que les prévisions restent précises." },
  "No risks ahead at the current trends for {s}. Keep logging so the predictions stay accurate.": { "es": "No hay riesgos por delante para {s} con las tendencias actuales. Sigue registrando para que las predicciones sean precisas.", "pt": "Sem riscos à frente para {s} com as tendências atuais. Continue registrando para manter as previsões precisas.", "fr": "Aucun risque à venir pour {s} avec les tendances actuelles. Continuez à noter pour que les prévisions restent précises." },
  "If nothing changes:": { "es": "Si nada cambia:", "pt": "Se nada mudar:", "fr": "Si rien ne change :" },
  "— {s}": { "es": "— {s}", "pt": "— {s}", "fr": "— {s}" },
  "Source: NovaCare prediction engine (trend projection, dose rate, bone-loss model) on your logged readings.": { "es": "Fuente: motor de predicción de NovaCare (proyección de tendencias, tasa de dosis, modelo de pérdida ósea) sobre tus mediciones registradas.", "pt": "Fonte: motor de previsão do NovaCare (projeção de tendências, taxa de dose, modelo de perda óssea) sobre suas medições registradas.", "fr": "Source : moteur de prévision NovaCare (projection des tendances, débit de dose, modèle de perte osseuse) sur vos mesures enregistrées." },
  "Source: NovaCare prediction engine (trend projection, dose rate, bone-loss model) on their logged readings.": { "es": "Fuente: motor de predicción de NovaCare (proyección de tendencias, tasa de dosis, modelo de pérdida ósea) sobre sus mediciones registradas.", "pt": "Fonte: motor de previsão do NovaCare (projeção de tendências, taxa de dose, modelo de perda óssea) sobre as medições registradas.", "fr": "Source : moteur de prévision NovaCare (projection des tendances, débit de dose, modèle de perte osseuse) sur ses mesures enregistrées." },
  "No onboard protocol for this question.": { "es": "No hay un protocolo a bordo para esta pregunta.", "pt": "Não há protocolo de bordo para esta pergunta.", "fr": "Aucun protocole de bord pour cette question." },
  "NovaCare only answers from its knowledge base (v{s}) and the rules engine, so it will not guess.": { "es": "NovaCare solo responde con su base de conocimiento (v{s}) y el motor de reglas, así que no va a adivinar.", "pt": "O NovaCare só responde com sua base de conhecimento (v{s}) e o motor de regras, então não vai adivinhar.", "fr": "NovaCare ne répond qu’à partir de sa base de connaissances (v{s}) et du moteur de règles, il ne devinera donc pas." },
  "Escalate: ask the Crew Medical Officer, or send the question to ground — {s}": { "es": "Avisa: pregunta al oficial médico de la tripulación o envía la pregunta al control en tierra — {s}", "pt": "Avise: pergunte ao oficial médico da tripulação ou envie a pergunta ao controle em terra — {s}", "fr": "Alertez : demandez à l’officier médical de l’équipage ou envoyez la question au contrôle au sol — {s}" },
  "ground can answer in near real-time.": { "es": "el control en tierra puede responder casi en tiempo real.", "pt": "o controle em terra pode responder quase em tempo real.", "fr": "le contrôle au sol peut répondre quasiment en temps réel." },
  "a ground reply can take 40+ minutes round-trip, so begin onboard care first.": { "es": "una respuesta de tierra puede tardar más de 40 minutos entre ida y vuelta, así que empieza primero la atención a bordo.", "pt": "uma resposta do controle em terra pode levar mais de 40 minutos entre ida e volta; comece primeiro o atendimento a bordo.", "fr": "une réponse du sol peut prendre plus de 40 minutes aller-retour : commencez d’abord les soins à bord." },
  "ground can answer within seconds.": { "es": "el control en tierra puede responder en segundos.", "pt": "o controle em terra pode responder em segundos.", "fr": "le contrôle au sol peut répondre en quelques secondes." },
  "a ground reply can take up to 44 minutes round-trip, so begin onboard care first.": { "es": "una respuesta de tierra puede tardar hasta 44 minutos entre ida y vuelta, así que empieza primero la atención a bordo.", "pt": "uma resposta do controle em terra pode levar até 44 minutos entre ida e volta; comece primeiro o atendimento a bordo.", "fr": "une réponse du sol peut prendre jusqu’à 44 minutes aller-retour : commencez d’abord les soins à bord." },
  "contact base first; link to ground is relayed and may be delayed.": { "es": "contacta primero con la base; el enlace con tierra es retransmitido y puede tener retraso.", "pt": "contate primeiro a base; o enlace com a terra é retransmitido e pode atrasar.", "fr": "contactez d’abord la base ; la liaison avec le sol est relayée et peut être retardée." },
  "Space station (low Earth orbit)": { "es": "Estación espacial (órbita terrestre baja)", "pt": "Estação espacial (órbita baixa da Terra)", "fr": "Station spatiale (orbite terrestre basse)" },
  "Deep-space transit vehicle": { "es": "Vehículo de tránsito en el espacio profundo", "pt": "Veículo de trânsito no espaço profundo", "fr": "Véhicule de transit en espace lointain" },
