  "You have no readings yet. A check-in takes about two minutes.": { "es": "Aún no tienes mediciones. Un chequeo lleva unos dos minutos.", "pt": "Você ainda não tem medições. Um check-in leva cerca de dois minutos.", "fr": "Vous n’avez pas encore de mesures. Un bilan prend environ deux minutes." },
  "There are no readings yet. A check-in takes about two minutes.": { "es": "Aún no hay mediciones. Un chequeo lleva unos dos minutos.", "pt": "Ainda não há medições. Um check-in leva cerca de dois minutos.", "fr": "Il n’y a pas encore de mesures. Un bilan prend environ deux minutes." },
