  "This week, focus on {s}. · Readiness down {n} in {n} days": { "es": "Esta semana, céntrate en {s}. · Preparación −{n} en {n} días", "pt": "Nesta semana, foque em {s}. · Prontidão −{n} em {n} dias", "fr": "Cette semaine, concentrez-vous sur {s}. · Aptitude −{n} en {n} jours" },
  "This week, focus on {s}.": { "es": "Esta semana, céntrate en {s}.", "pt": "Nesta semana, foque em {s}.", "fr": "Cette semaine, concentrez-vous sur {s}." },
